answer.sql:
SELECT *
FROM policy
WHERE strftime(Effective_Date, '%Y') = '2019';

SELECT Effective_Date
FROM policy
WHERE Policy_Identifier = 31003000337;

SELECT Expiration_Date
FROM policy
WHERE Policy_Number = 31003000336;

SELECT COUNT(*) AS count
FROM catastrophe
WHERE Catastrophe_Name IS NOT NULL;

SELECT Line_1_Address
FROM location_address
WHERE Postal_Code = 78704;

SELECT COUNT(*) AS count
FROM fire_claim
WHERE Fireplace IS NOT NULL;

SELECT COUNT(*) AS count
FROM fire_claim
WHERE Fireplace IS NULL OR Fireplace = '';

SELECT COUNT(*) AS fire_loss_records
FROM fire_claim
WHERE Year_Built < 1980;

SELECT COUNT(*) AS count
FROM fire_claim
WHERE Year_Built >= 2010;

SELECT COUNT(*) AS count
FROM fire_claim
WHERE Nearest_Firestation_miles <= 3;

SELECT COUNT(*)
FROM fire_claim
WHERE Nearest_Firestation_miles >= 15;

SELECT COUNT(*)
FROM fire_claim
WHERE Number_of_Firefighters < 6;

SELECT COUNT(*)
FROM fire_claim
WHERE Number_of_Firefighters >= 9;

SELECT COUNT(*) AS count
FROM fire_claim
WHERE Loss_Ratio > 1;

SELECT COUNT(*) AS count
FROM fire_claim
WHERE Loss_Ratio < 0.4;

SELECT Nearest_Firestation_miles, Loss_Ratio
FROM fire_claim
WHERE Nearest_Firestation_miles = 1;

SELECT Year_Built, Fireplace
FROM fire_claim
WHERE Year_Built BETWEEN 1990 AND 1999;

SELECT Fireplace, Loss_Ratio
FROM fire_claim
WHERE Nearest_Firestation_miles >= 10;

SELECT Year_Built, Fireplace
FROM fire_claim
WHERE Number_of_Firefighters < 5;

SELECT Number_of_Firefighters, Loss_Ratio
FROM fire_claim
WHERE Year_Built > 2015;

SELECT Year_Built, Nearest_Firestation_miles
FROM fire_claim
WHERE Loss_Ratio < 0.2;

SELECT AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
WHERE Year_Built < 1980;

SELECT MEDIAN(Loss_Ratio) AS median_loss_ratio
FROM fire_claim
WHERE Year_Built >= 2010;

SELECT AVG(Number_of_Firefighters) AS average_number_of_firefighters
FROM fire_claim
WHERE Fireplace IS NULL OR Fireplace = '';

SELECT AVG(Year_Built) AS average_construction_year
FROM fire_claim
WHERE Nearest_Firestation_miles > 10;

SELECT MAX(Loss_Ratio)
FROM fire_claim
WHERE Nearest_Firestation_miles <= 3;

SELECT MEDIAN(Nearest_Firestation_miles) AS median_station_distance
FROM fire_claim
WHERE Number_of_Firefighters < 6;

SELECT MIN(Year_Built) AS earliest_home_construction_year
FROM fire_claim
WHERE Loss_Ratio > 1;

SELECT MAX(Nearest_Firestation_miles)
FROM fire_claim
WHERE Loss_Ratio < 0.4;

SELECT COUNT(*) AS policy_count
FROM policy
WHERE strftime(Effective_Date, '%Y') = '2019';

SELECT COUNT(*) AS claim_count
FROM claim
WHERE Claim_Open_Date > '2019-05-31';

SELECT AVG(claim_amount.Claim_Amount) AS average_claim_amount
FROM claim_amount
WHERE claim_amount.Claim_Identifier > 1;

